async function saveHeroConfirmation(){if(!pendingHeroSquadId)return;const selects=[...document.querySelectorAll("#heroConfirmRows select[data-hero-slot]")],values=selects.map(x=>String(x.value||"").trim());const st=$("#scanStatus"),btn=$("#saveHeroNamesBtn");if(values.length!==5||values.some(v=>!v)){st.className="notice warn";st.textContent=t("hero_all_required");return}if(new Set(values).size!==values.length){st.className="notice warn";st.textContent=t("hero_duplicate");return}const id=pendingHeroSquadId,next=JSON.parse(JSON.stringify(state)),sq=next.squads?.[id-1];if(!sq){st.className="notice warn";st.textContent=t("hero_save_failed");return}values.forEach((value,i)=>{if(!sq.heroes[i])sq.heroes[i]=emptyHero(i+1);sq.heroes[i].name=canonicalStoredHeroName(value)});const now=new Date().toISOString();sq.updated_at=now;next.updated_at=now;next.version="1.6.3";if(btn){btn.disabled=true;btn.textContent=t("syncing")}st.className="notice";st.textContent=t("hero_saving");try{let persisted=next;if(cloudSession?.access_token){const r=await fetch("/api/state",{method:"POST",headers:authHeaders({"content-type":"application/json"}),body:JSON.stringify({state:next})}),j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.message||"hero_save_failed");if(j?.state)persisted=mergeState(next,j.state)}state=persisted;state.version="1.6.3";localStorage.setItem(STORE_KEY,JSON.stringify(state));render();st.className="notice";st.textContent=t("hero_confirm_saved");closeHeroConfirmation(true)}catch{st.className="notice warn";st.textContent=t("hero_save_failed");if(btn){btn.disabled=false;btn.textContent=t("hero_save")}}}
async function skipHeroConfirmation(){if(!pendingHeroSquadId){closeHeroConfirmation(true);return}const id=pendingHeroSquadId,next=JSON.parse(JSON.stringify(state)),sq=next.squads?.[id-1],st=$("#scanStatus"),btn=$("#skipHeroNamesBtn");if(sq?.heroes)for(const h of sq.heroes){if(isGenericHeroName(h?.name))h.name=""}next.version="1.6.3";if(btn)btn.disabled=true;st.className="notice";st.textContent=t("syncing");try{let persisted=next;if(cloudSession?.access_token){const r=await fetch("/api/state",{method:"POST",headers:authHeaders({"content-type":"application/json"}),body:JSON.stringify({state:next})}),j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.message||"hero_save_failed");if(j?.state)persisted=mergeState(next,j.state)}state=persisted;state.version="1.6.3";localStorage.setItem(STORE_KEY,JSON.stringify(state));render();st.className="notice";st.textContent=t("hero_confirm_skipped");closeHeroConfirmation(true)}catch{st.className="notice warn";st.textContent=t("hero_save_failed");if(btn)btn.disabled=false}}

function inlineHeroConfirmationHtml(sq,squadId){const rows=Array.from({length:5},(_,i)=>{const h=sq.heroes?.[i]||emptyHero(i+1),saved=isGenericHeroName(h?.name)?"":canonicalStoredHeroName(h.name);return `<div class="inlineHeroConfirmRow"><span class="inlineHeroSlot">${i+1}</span><select class="fieldSelect inlineHeroSelect" data-inline-hero-slot="${i}">${heroConfirmOptions(saved)}</select></div>`}).join("");return `<div class="inlineHeroConfirm" data-inline-confirm="${squadId}"><div class="inlineHeroConfirmHead"><div><b>${esc(t("hero_confirm_title",{squad:squadId}))}</b><small>${esc(t("hero_confirm_help"))}</small></div><span class="pill">${esc(t("hero_confirm_badge"))}</span></div><div class="inlineHeroConfirmRows">${rows}</div><div class="notice warn hidden" data-inline-hero-status></div><button class="primaryAction inlineHeroSaveBtn" type="button" data-inline-hero-save="${squadId}">${esc(t("hero_save"))}</button></div>`}
async function saveInlineHeroNames(squadId,container,button=null){
  const id=Number(squadId);
  if(!Number.isInteger(id)||id<1||id>4||!container)return;
  const selects=[...container.querySelectorAll("select[data-inline-hero-slot]")];
  const values=selects.map(x=>String(x.value||"").trim());
  const status=container.querySelector("[data-inline-hero-status]");
  const show=(key,warn=true)=>{if(status){status.className=`notice${warn?" warn":""}`;status.textContent=t(key)}};
  if(values.length!==5||values.some(v=>!v))return show("hero_all_required");
  if(new Set(values).size!==values.length)return show("hero_duplicate");
  const next=JSON.parse(JSON.stringify(state));
  const sq=next.squads?.[id-1];
  if(!sq)return show("hero_save_failed");
  values.forEach((value,i)=>{if(!sq.heroes[i])sq.heroes[i]=emptyHero(i+1);sq.heroes[i].name=canonicalStoredHeroName(value)});
  const now=new Date().toISOString();
  sq.updated_at=now;next.updated_at=now;next.version="1.6.3";
  if(button){button.disabled=true;button.textContent=t("syncing")}
  show("hero_saving",false);
  try{
    let persisted=next;
    if(cloudSession?.access_token){
      const r=await fetch("/api/state",{method:"POST",headers:authHeaders({"content-type":"application/json"}),body:JSON.stringify({state:next})});
      const j=await r.json().catch(()=>({}));
      if(!r.ok)throw new Error(j.message||"hero_save_failed");
      if(j?.state)persisted=mergeState(next,j.state);
    }
    state=persisted;state.version="1.6.3";
    localStorage.setItem(STORE_KEY,JSON.stringify(state));
    render();
    requestAnimationFrame(()=>{const squads=[...document.querySelectorAll("#squadList .squad")];squads[id-1]?.classList.add("open")});
  }catch{
    show("hero_save_failed");
    if(button){button.disabled=false;button.textContent=t("hero_save")}
  }
}

let languageChoice=localStorage.getItem(LANG_KEY)||"auto",lang=resolveLanguage(languageChoice),locale=localeFor(lang),t=translator(lang);
