function renderProPriority(analysis){
  const ui=aiUiText(),panel=$("#proPriorityPanel"),summary=$("#proPrioritySummary"),list=$("#proPriorityList"),compare=$("#proSquadCompare"),confidence=$("#proConfidence"),note=$("#playerSyncInfo"),shopList=$("#proShopList"),shopSummary=$("#proShopSummary"),shopConfidence=$("#shopConfidence"),shopCatalogPill=$("#shopCatalogPill"),avoid=$("#proAvoidList");
  if(!panel||!analysis)return;
  if(note)note.classList.add("hidden");panel.classList.remove("hidden");
  if(summary){
    const mi=analysis.meta_intelligence,composition=analysis.composition?.label?` · ${analysis.composition.label}`:"";
    summary.textContent=`${analysis.summary||""}${composition}${analysis.candidates_evaluated?` · ${analysis.candidates_evaluated} ${ui.evaluated}`:""}${mi?.source_count?` · AI sources ${mi.source_count} · Meta ${mi.confidence}%`:""}`;
  }
  if(confidence)confidence.textContent=analysis.confidence_label||`${analysis.confidence||0}%`;
  if(list){
    const items=(Array.isArray(analysis.priorities)?analysis.priorities:[]).slice(0,3);
    list.innerHTML=items.length?items.map(x=>`<article class="priorityCard compactDecision"><span class="priorityRank">${esc(x.rank||"•")}</span><div class="priorityMain"><div class="decisionHead"><b>${esc(x.title||"")}${x.target?` · ${esc(x.target)}`:""}</b><span class="decisionMetric">${esc(ui.impact)} : ${esc(x.impact_label||"—")} · ${esc(ui.roi)} : ${esc(x.resource_efficiency_label||x.roi_label||"—")}${Array.isArray(x.evidence_ids)&&x.evidence_ids.length?` · ${x.evidence_ids.length} src`:""}</span></div><strong>${esc(x.action||"")}</strong><details class="decisionDetails"><summary>${esc(ui.why)}</summary><p>${esc(x.reason||"")}</p><small>🆓 ${esc(x.buy_free||"")}</small><small>💎 ${esc(x.buy_paid||"")}</small></details></div></article>`).join(""):`<div class="notice">${esc(analysis.summary||t("player_sync_note"))}</div>`;
  }
  if(avoid){
    const rows=Array.isArray(analysis.avoid_now)?analysis.avoid_now:[];
    avoid.innerHTML=rows.length?`<div class="avoidTitle">⛔ ${esc(ui.avoid)}</div>${rows.map(x=>`<div class="avoidRow">${esc(x)}</div>`).join("")}`:"";
  }
  if(compare){
    const rows=Array.isArray(analysis.squads)?analysis.squads:[];
    compare.innerHTML=rows.map(x=>`<div class="compareRow"><span class="compareNo">${esc(x.id)}</span><div><b>${esc(x.name||`${t("squad")} ${x.id}`)}</b><small>${esc(x.status||"")}${x.optional?"":` · ${t("pro_data_quality")} ${esc(x.data_quality??0)}% · ${esc(x.heroes_detected??0)}/5 ${esc(ui.heroes)}`}${x.composition_complete?" ✓":""}</small></div><strong>${esc(x.power_label||"—")}</strong></div>`).join("");
  }
  const shop=analysis.shop||{};
  if(shopSummary)shopSummary.textContent=shop.summary||t("shop_summary_default");
  if(shopConfidence)shopConfidence.textContent=shop.confidence_label||`${shop.confidence||0}%`;
  if(shopCatalogPill){shopCatalogPill.textContent=shop.catalog_label||"—";shopCatalogPill.className=`pill ${shop.catalog_status==="official"?"catalogOfficialPill":"catalogPartialPill"}`;}
  if(shopList){
    const rows=(Array.isArray(shop.recommendations)?shop.recommendations:[]).slice(0,3);
    shopList.innerHTML=rows.length?rows.map(x=>`<article class="shopCard ${esc(x.verdict_key||"")}"><div class="shopHead"><span class="shopRank">${esc(x.rank||"•")}</span><div><b>${esc(x.item||"")}</b><small>${esc(x.store||"")}${x.price_label?` · ${esc(x.price_label)}`:""}</small>${x.score_label?`<span class="shopScore">${esc(x.score_label)}</span>`:""}</div><span class="shopVerdict">${esc(x.verdict||"")}</span></div><details class="decisionDetails"><summary>${esc(ui.details)}</summary><p>${esc(x.reason||"")}</p>${x.target?`<strong>${esc(x.target)}</strong>`:""}</details></article>`).join(""):`<div class="notice">${esc(t("shop_no_recommendations"))}</div>`;
  }
}

function memberActivity(m){
  const now=Date.now(),ts=Date.parse(m?.last_active_at||m?.updated_at||"");
  const ageH=Number.isFinite(ts)?Math.max(0,(now-ts)/36e5):null;
  let score=0,signals=0;
  if(ageH!==null){signals++;score+=ageH<=24?55:ageH<=72?42:ageH<=168?24:8}
  const delta=Number(m?.delta_m);if(Number.isFinite(delta)){signals++;score+=delta>0?25:delta===0?8:4}
  const vs=Number(m?.vs_points);if(Number.isFinite(vs)){signals++;score+=vs>0?12:2}
  const season=Number(m?.season_points);if(Number.isFinite(season)){signals++;score+=season>0?8:1}
  if(!signals)return {score:null,key:"unknown",ageH:null};
  score=Math.max(0,Math.min(100,Math.round(score)));
  const key=score>=72?"very_active":score>=52?"active":score>=28?"low": "inactive";
  return {score,key,ageH};
}
function renderAllianceActivity(){
  const members=state.alliance.members||[],box=$("#activitySummary"),counts={active:0,watch:0,inactive:0,unknown:0};
  const scored=members.map(m=>({m,a:memberActivity(m)}));
  scored.forEach(({a})=>{if(a.key==="very_active"||a.key==="active")counts.active++;else if(a.key==="low")counts.watch++;else if(a.key==="inactive")counts.inactive++;else counts.unknown++});
  if(box)box.innerHTML=`<div><b>🟢 ${counts.active}</b><small>${esc(t("activity_active"))}</small></div><div><b>🟠 ${counts.watch}</b><small>${esc(t("activity_watch"))}</small></div><div><b>🔴 ${counts.inactive}</b><small>${esc(t("activity_inactive"))}</small></div>`;
  const note=$("#activityNote");if(note)note.textContent=members.length?t("activity_estimated_note"):t("activity_no_data");
  return scored;
}
function renderMembers(){const box=$("#memberList"),members=state.alliance.members||[];if(!box)return;renderAllianceActivity();box.innerHTML=members.length?members.map(m=>{const a=memberActivity(m),icon=a.key==="very_active"||a.key==="active"?"🟢":a.key==="low"?"🟠":a.key==="inactive"?"🔴":"⚪",label=t(`activity_${a.key}`),score=a.score===null?"—":`${a.score}/100`;return `<div class="member"><div><b>${icon} ${esc(m.name||t("player"))}</b><small>${t("hq")} ${m.hq_level??"—"} · ${fmtPower(m.power_m)} · ${m.role||"R1"}</small><span class="activityLine">${esc(label)} · ${esc(score)}</span></div><div class="delta">${m.delta_m?`${m.delta_m>0?"+":""}${m.delta_m} M`:"—"}</div></div>`}).join(""):`<div class="notice">${t("no_members")}</div>`}
